<div class="dashboard-heading"><div><span class="eyebrow">ATENDIMENTO</span><h2>Mensagens</h2><p>Converse diretamente com as lojas.</p></div></div><section class="panel conversation-list"><?php foreach($conversations as $conversation):?><a href="<?= e(url('/minha-conta/mensagens/'.$conversation['id'])) ?>"><div class="message-avatar"><?= e(mb_substr($conversation['store_name'],0,1)) ?></div><div><strong><?= e($conversation['store_name']) ?></strong><span><?= e($conversation['subject']) ?></span><small><?= e(mb_strimwidth($conversation['last_message']??'',0,100,'…')) ?></small></div><time><?= date('d/m H:i',strtotime($conversation['last_message_at']?:$conversation['created_at'])) ?></time></a><?php endforeach;?><?php if(!$conversations):$emptyTitle='Nenhuma conversa';$emptyText='Abra uma conversa pela página de uma loja.';require dirname(__DIR__,2).'/components/dashboard/empty-state.php';endif;?></section>
